cat <<'EOF' > app/javascript/controllers/option_rows_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["list", "row", "template"]

  add() {
    const fragment = this.templateTarget.content.cloneNode(true)
    this.listTarget.appendChild(fragment)
    this.reindex()

    const rows = this.rowTargets
    const lastRow = rows[rows.length - 1]
    const input = lastRow?.querySelector('[data-input="body"]')
    if (input) input.focus()
  }

  remove(event) {
    const row = event.currentTarget.closest('[data-option-rows-target="row"]')
    if (!row) return
    row.remove()
    this.reindex()
  }

  reindex() {
    this.rowTargets.forEach((row, index) => {
      const num = index + 1
      const bodyId = `question_option_rows_${index}_body`
      const correctId = `question_option_rows_${index}_correct`

      const idInput = row.querySelector('[data-input="id"]')
      if (idInput) {
        idInput.name = `question[option_rows][${index}][id]`
      }

      const bodyLabel = row.querySelector('[data-label="body"]')
      if (bodyLabel) {
        bodyLabel.setAttribute("for", bodyId)
        bodyLabel.textContent = `Option ${num}`
      }

      const bodyInput = row.querySelector('[data-input="body"]')
      if (bodyInput) {
        bodyInput.id = bodyId
        bodyInput.name = `question[option_rows][${index}][body]`
        bodyInput.setAttribute("aria-label", `Option ${num}`)
      }

      const correctHiddenLabel = row.querySelector('[data-label="correct"]')
      if (correctHiddenLabel) {
        correctHiddenLabel.setAttribute("for", correctId)
        correctHiddenLabel.textContent = `Option ${num} is correct`
      }

      const checkboxLabel = row.querySelector('[data-checkbox-label]')
      if (checkboxLabel) {
        checkboxLabel.setAttribute("for", correctId)
      }

      const correctHidden = row.querySelector('[data-input="correct-hidden"]')
      if (correctHidden) {
        correctHidden.name = `question[option_rows][${index}][correct]`
      }

      const correctInput = row.querySelector('[data-input="correct"]')
      if (correctInput) {
        correctInput.id = correctId
        correctInput.name = `question[option_rows][${index}][correct]`
        correctInput.setAttribute("aria-label", `Option ${num} is correct`)
      }

      const removeBtn = row.querySelector('[data-remove-btn]')
      if (removeBtn) {
        removeBtn.setAttribute("aria-label", `Remove option ${num}`)
      }
    })
  }
}
EOF

cat <<'EOF' > app/javascript/controllers/preview_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = {
    questions: Array
  }

  static targets = [
    "questionScreen",
    "resultScreen",
    "progress",
    "body",
    "options",
    "status",
    "nextButton",
    "scoreText"
  ]

  connect() {
    this.restart()
  }

  restart() {
    this.index = 0
    this.score = 0
    this.answered = false
    if (this.hasResultScreenTarget) this.resultScreenTarget.hidden = true
    if (this.hasQuestionScreenTarget) this.questionScreenTarget.hidden = false
    this.renderQuestion()
  }

  pick(event) {
    if (this.answered) return
    this.answered = true

    const button = event.currentTarget
    const optionIndex = Number(button.dataset.optionIndex)
    const question = this.questionsValue[this.index]
    const pickedOption = question.options[optionIndex]
    const isCorrect = Boolean(pickedOption && pickedOption.correct)

    if (isCorrect) {
      this.score += 1
    }

    this.optionsTarget.classList.add("is-locked", "is-revealed")
    button.classList.add("is-picked")

    const optionButtons = this.optionsTarget.querySelectorAll("button.play-option")
    optionButtons.forEach((btn, idx) => {
      btn.disabled = true
      const opt = question.options[idx]
      if (opt && opt.correct) {
        btn.classList.add("is-correct")
        const mark = document.createElement("span")
        mark.className = "play-option__mark"
        mark.textContent = "✓"
        btn.appendChild(mark)
      }
    })

    this.statusTarget.hidden = false
    this.statusTarget.className = isCorrect ? "play-status play-status--right" : "play-status play-status--wrong"
    this.statusTarget.textContent = isCorrect ? "Correct!" : "Wrong!"

    const isLast = this.index >= this.questionsValue.length - 1
    this.nextButtonTarget.hidden = false
    this.nextButtonTarget.textContent = isLast ? "See score" : "Next question"
  }

  advance() {
    if (this.index < this.questionsValue.length - 1) {
      this.index += 1
      this.answered = false
      this.renderQuestion()
    } else {
      this.showScore()
    }
  }

  showScore() {
    this.questionScreenTarget.hidden = true
    this.resultScreenTarget.hidden = false
    this.scoreTextTarget.textContent = `Score: ${this.score}/${this.questionsValue.length}`
  }

  renderQuestion() {
    if (!this.questionsValue || this.questionsValue.length === 0) return

    const total = this.questionsValue.length
    const question = this.questionsValue[this.index]

    this.progressTarget.textContent = `Question ${this.index + 1} of ${total}`
    this.bodyTarget.textContent = question.body

    this.optionsTarget.className = "play-options"
    this.optionsTarget.innerHTML = ""

    question.options.forEach((option, idx) => {
      const btn = document.createElement("button")
      btn.type = "button"
      btn.className = "play-option"
      btn.dataset.optionIndex = idx
      btn.dataset.action = "preview#pick"

      const letter = document.createElement("span")
      letter.className = "play-option__letter"
      letter.textContent = option.letter

      const title = document.createElement("span")
      title.className = "play-option__title"
      title.textContent = option.body

      btn.appendChild(letter)
      btn.appendChild(title)
      this.optionsTarget.appendChild(btn)
    })

    this.statusTarget.hidden = true
    this.statusTarget.textContent = ""
    this.statusTarget.className = "play-status"

    this.nextButtonTarget.hidden = true
  }
}
EOF

